using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Fourier;

internal sealed class CharacterOrbitFieldDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The generated character field records the exact doubling period and its self-pairing involution.",
        H("Character Orbit Fields"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("character-orbit-degree"),
                DeclarationHandle.Create("D5/S3/Fourier/CharacterOrbitField.character_orbit_degree"),
                H("Degree equals the actual doubling period"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                        Paragraph(Text("Let n be any odd natural number at least three, d any natural number, F any finite field of characteristic two, and zeta a primitive nth root in F. For t in (ZMod n)^(Fin d), let K(t) be the intermediate field generated over ZMod 2 by the elements zeta^(t(i).val). Multiplication by two is a permutation p of the character index group. The degree of K(t) over ZMod 2 equals the minimal period of t under p. The zero index, d=0, and composite odd n are included. F need not be generated by zeta.")),
                        Paragraph(Text("Write phi for the prime-field Frobenius automorphism of K(t). Its lth power fixes each generator precisely when p iterated l times fixes t. Injectivity of the primitive character proves one direction; equality on the generating set extends to equality of algebra homomorphisms in the other direction. The order of finite-field Frobenius is the extension degree. Equality of the sets of periods therefore identifies that degree with the minimal orbit period."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("self-paired-character-involution"),
                DeclarationHandle.Create("D5/S3/Fourier/CharacterOrbitField.self_paired_character_involution"),
                H("The involution of an actual nonzero self-paired character field"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                        Paragraph(Text("Under the same hypotheses, suppose an actual iterate p^j(t) equals -t and t is nonzero. Then K(t) has a nonidentity involutive ring automorphism sigma sending every generator zeta^(t(i).val) to its inverse. The minimal doubling period of t is even. No involution or parity is supplied as an additional hypothesis.")),
                        Paragraph(Text("Take sigma to be the jth power of Frobenius. The index relation identifies its action on generators with inversion. Doubling commutes with negation, so the 2jth iterate fixes t; the degree-period equality makes sigma squared the identity on the entire generated field. If sigma were the identity, primitive-root injectivity would give t=-t. Odd n makes multiplication by two injective, forcing t=0. The fixed-field extension then has degree two, so the prime-field degree of K(t) is even. These are finite-field structural statements; they do not evaluate a replica contraction."))),
                DescribeRole.Theorem))));
}
